/**
 * Restarts the observation id sequence after the 0003 and 0004 rebuilds.
 *
 * @since 0.1.0
 */

import * as Dialect from "@smthrs/database/Dialect"
import * as Effect from "effect/Effect"
import * as SqlClient from "effect/sql/SqlClient"

/**
 * Moves the PostgreSQL identity of `flows_scores.id` past the largest stored id.
 *
 * Migrations 0003 and 0004 copied every row with its explicit id into a new
 * `GENERATED BY DEFAULT AS IDENTITY` column. PostgreSQL does not advance an
 * identity for explicit values, so the rebuilt table's sequence restarted at 1
 * and the next insert for each copied id failed with a duplicate key. Landed
 * migrations are never edited, so this one repairs every store that already
 * ran them. SQLite needs nothing: `AUTOINCREMENT` continues past the largest
 * rowid.
 *
 * @category migrations
 * @since 0.1.0
 */
export const migration: Effect.Effect<void, unknown, SqlClient.SqlClient> = Effect.gen(function*() {
  const sql = yield* SqlClient.SqlClient
  if (!Dialect.isPostgres(sql)) return
  yield* sql`SELECT setval(
    pg_get_serial_sequence('flows_scores', 'id'),
    COALESCE((SELECT max(id) FROM flows_scores), 0) + 1,
    false
  )`
})
